import { pascal, camel } from "./compiler.mjs";

export const banner =
  "// Generated by pnpm generate:sdk. Do not edit directly.\n";
export function text(value = "") {
  return value
    .replace(
      /\]\((#[^)]*|\/[^)]*)\)/g,
      (_, url) =>
        `](${url.startsWith("#") ? "https://docs.facturapi.io/api/" : "https://docs.facturapi.io"}${url})`,
    )
    .replaceAll("*/", "* /");
}
export function doc(value, indent = "") {
  return `${indent}/// <summary>\n${text(value)
    .split("\n")
    .map(
      (line) =>
        `${indent}/// ${line.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")}`,
    )
    .join("\n")}\n${indent}/// </summary>\n`;
}
export function fieldType(field, optional = true) {
  const type =
    field.kind === "model"
      ? field.ref
      : field.kind === "array"
        ? `${fieldType(field.item, false)}[]`
        : {
            string: "string",
            date: "DateTime",
            boolean: "bool",
            integer: "int",
            number: "double",
          }[field.kind];
  return ["boolean", "integer", "number", "date"].includes(field.kind) &&
    (field.nullable || (optional && !field.required))
    ? type + "?"
    : type;
}
export function description(field) {
  return [
    field.description || field.name,
    field.values &&
      `Valores: ${field.values.map((value) => JSON.stringify(value)).join(", ")}.`,
    field.required ? "Requerido." : "Opcional.",
    field.nullable && "Admite null.",
  ]
    .filter(Boolean)
    .join("\n");
}

export function renderModels(contract) {
  const outputs = new Map();
  for (const model of contract.models) {
    const name =
      model.name === "CustomerSearchResult"
        ? "SearchResult<T>"
        : model.name === "TaxInfoValidationError"
          ? "TaxInfoError"
          : model.name;
    let content =
      banner +
      "using System;\nusing System.Collections.Generic;\nusing Newtonsoft.Json;\n\nnamespace Facturapi\n{\n";
    content +=
      doc(
        model.name === "CustomerSearchResult"
          ? "Resultados paginados."
          : model.description,
        "    ",
      ) +
      `    public class ${name}${model.input ? " : Dictionary<string, object>" : ""}\n    {\n`;
    const required = model.input
      ? model.properties.filter((field) => field.required)
      : [];
    if (required.length) {
      content += doc(`Crea ${name}.`, "        ");
      for (const field of required)
        content += `        /// <param name="${camel(field.name)}">${text(description(field)).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll("\n", " ")}</param>\n`;
      content += `        public ${name}(${required.map((field) => `${fieldType(field)} ${camel(field.name)}`).join(", ")})\n        {\n${required.map((field) => `            this[${JSON.stringify(field.name)}] = ${camel(field.name)};`).join("\n")}\n        }\n\n`;
    }
    for (const field of model.properties) {
      const type =
        model.name === "CustomerSearchResult" && field.name === "data"
          ? "List<T>"
          : field.kind === "array" &&
              field.item.ref === "TaxInfoValidationError"
            ? "TaxInfoError[]"
            : fieldType(field);
      content += doc(description(field), "        ");
      if (model.input)
        content += `        [JsonIgnore]\n        public ${type} ${pascal(field.name)}\n        {\n            get => TryGetValue(${JSON.stringify(field.name)}, out var value) ? (${type})value : default;\n            set => this[${JSON.stringify(field.name)}] = value;\n        }\n\n`;
      else
        content += `        [JsonProperty(${JSON.stringify(field.name)})]\n        public ${type} ${pascal(field.name)} { get; set; }\n\n`;
    }
    content += "    }\n}\n";
    outputs.set(
      `Models/${model.input ? "Inputs/" : ""}${name.replace("<T>", "")}.cs`,
      content,
    );
  }
  return outputs;
}
